<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Glimpse of pathogenesis</title>
<style>
  body {
    margin: 0;
    padding: 20px 30px;
    background-color: #ffffff;
    font-family: "Times New Roman", Times, Georgia, serif;
    color: #000000;
  }

  .slide-container {
    max-width: 1100px;
    margin: 0 auto;
    position: relative;
  }

  /* Header Section */
  .header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
    padding: 0 10px;
  }

  .logo-left, .logo-right {
    flex: 0 0 80px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
  }

  .logo-left img, .logo-right img {
    max-height: 80px;
    width: auto;
  }

  .logo-placeholder {
    width: 75px;
    height: 75px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-size: 10px;
    text-align: center;
  }

  /* SVG recreation for ICAR logo */
  .icar-logo {
    width: 65px;
    height: 70px;
  }

  /* SVG recreation for IVRI logo */
  .ivri-logo {
    width: 65px;
    height: 70px;
  }

  .title {
    flex: 1;
    text-align: center;
    font-size: 38px;
    font-weight: bold;
    color: #d11212;
    margin: 0 10px;
    letter-spacing: 0.5px;
  }

  /* Table Styles */
  .table-container {
    width: 100%;
    overflow-x: auto;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11.5px;
    line-height: 1.25;
    font-family: Arial, Helvetica, sans-serif;
  }

  th {
    background-color: #ffffff;
    color: #000000;
    font-weight: bold;
    padding: 5px 4px;
    text-align: left;
    vertical-align: middle;
    border-top: 1.5px solid #8b0000;
    border-bottom: 1.5px solid #8b0000;
    border-left: 1px solid #993333;
    border-right: 1px solid #993333;
    font-family: "Times New Roman", Times, serif;
    font-size: 12.5px;
  }

  th:first-child {
    border-left: 1.5px solid #8b0000;
  }

  th:last-child {
    border-right: 1.5px solid #8b0000;
  }

  td {
    background-color: #faffd2;
    padding: 4px 5px;
    vertical-align: top;
    border-top: 1px solid #d6cca4;
    border-bottom: 1px solid #d6cca4;
    border-left: 1px solid #993333;
    border-right: 1px solid #993333;
  }

  td:first-child {
    border-left: 1.5px solid #8b0000;
  }

  td:last-child {
    border-right: 1.5px solid #8b0000;
  }

  tr:last-child td {
    border-bottom: 2.5px solid #8b0000;
  }

  /* Specific column widths */
  col.col-pathotype { width: 7.5%; }
  col.col-hosts { width: 15.5%; }
  col.col-site { width: 12%; }
  col.col-disease { width: 15%; }
  col.col-sources { width: 11%; }
  col.col-rx { width: 15%; }
  col.col-adhesion { width: 11%; }
  col.col-genetics { width: 13%; }

  .footer-citation {
    margin-top: 40px;
    text-align: right;
    font-size: 14px;
    font-weight: bold;
    color: #b81414;
    padding-right: 10px;
    font-family: Arial, Helvetica, sans-serif;
  }

  sup {
    font-size: 80%;
    line-height: 0;
  }
</style>
</head>
<body>

<div class="slide-container">

  <!-- Header -->
  <div class="header">
    <div class="logo-left">
      <!-- ICAR Logo Vector/Graphic -->
      <svg class="icar-logo" viewBox="0 0 100 110">
        <g fill="none" stroke="#237834" stroke-width="2.5" stroke-linecap="round">
          <!-- Wheat stalks -->
          <path d="M 50 80 C 50 50 30 35 15 20" />
          <path d="M 50 80 C 50 45 40 25 30 10" />
          <path d="M 50 80 C 50 40 47 20 45 5" />
          <path d="M 50 80 C 50 40 53 20 55 5" />
          <path d="M 50 80 C 50 45 60 25 70 10" />
          <path d="M 50 80 C 50 50 70 35 85 20" />
          <!-- Central stem grains -->
          <ellipse cx="50" cy="55" rx="8" ry="4" fill="#237834" stroke="none" transform="rotate(-30 50 55)"/>
          <ellipse cx="50" cy="55" rx="8" ry="4" fill="#237834" stroke="none" transform="rotate(30 50 55)"/>
          <ellipse cx="50" cy="42" rx="8" ry="4" fill="#237834" stroke="none" transform="rotate(-35 50 42)"/>
          <ellipse cx="50" cy="42" rx="8" ry="4" fill="#237834" stroke="none" transform="rotate(35 50 42)"/>
          <ellipse cx="50" cy="30" rx="8" ry="4" fill="#237834" stroke="none" transform="rotate(-40 50 30)"/>
          <ellipse cx="50" cy="30" rx="8" ry="4" fill="#237834" stroke="none" transform="rotate(40 50 30)"/>
        </g>
        <text x="50" y="93" font-size="9" font-family="sans-serif" font-weight="bold" fill="#237834" text-anchor="middle">भाकृअनुप</text>
        <text x="50" y="104" font-size="12" font-family="sans-serif" font-weight="bold" fill="#237834" text-anchor="middle">ICAR</text>
      </svg>
    </div>

    <div class="title">
      Glimpse of pathogenesis
    </div>

    <div class="logo-right">
      <!-- IVRI Logo Graphic -->
      <svg class="ivri-logo" viewBox="0 0 100 110">
        <circle cx="50" cy="45" r="32" fill="none" stroke="#4a154b" stroke-width="2.5" />
        <circle cx="50" cy="45" r="27" fill="none" stroke="#4a154b" stroke-width="1" />
        <!-- Caduceus / Cross emblem inside -->
        <path d="M 50 25 L 50 65 M 40 35 L 60 35 M 40 45 L 60 45" stroke="#4a154b" stroke-width="2" />
        <circle cx="50" cy="22" r="3" fill="#4a154b" />
        <!-- Gear / petals surround -->
        <g stroke="#4a154b" stroke-width="1.5" fill="none">
          <circle cx="50" cy="45" r="36" stroke-dasharray="3,3" />
        </g>
        <text x="50" y="90" font-size="8" font-family="sans-serif" font-weight="bold" fill="#4a154b" text-anchor="middle">I V R I</text>
      </svg>
    </div>
  </div>

  <!-- Table -->
  <div class="table-container">
    <table>
      <colgroup>
        <col class="col-pathotype">
        <col class="col-hosts">
        <col class="col-site">
        <col class="col-disease">
        <col class="col-sources">
        <col class="col-rx">
        <col class="col-adhesion">
        <col class="col-genetics">
      </colgroup>
      <thead>
        <tr>
          <th>Pathotype</th>
          <th>Host(s)</th>
          <th>Site</th>
          <th>Disease(S)</th>
          <th>Resevoir(S)/sources</th>
          <th>Rx</th>
          <th>Adhesion</th>
          <th>Genetic Identifiers</th>
        </tr>
      </thead>
      <tbody>
        <!-- tEPEC / aEPEC -->
        <tr>
          <td>tEPEC<br>aEPEC</td>
          <td>Children &lt;5 yr, adults at high inocula</td>
          <td>Small intestine</td>
          <td>Profuse watery diarrhea</td>
          <td>Humans<br>Humans, animals</td>
          <td>Oral rehydration, antibiotics for persistent cases</td>
          <td>Attaching and effacing</td>
          <td><i>eae</i><sup>+</sup>, <i>bfp</i><sup>+</sup>, <i>stx</i><sup>-</sup><br><i>eae</i><sup>+</sup>, <i>stx</i><sup>-</sup></td>
        </tr>

        <!-- STEC -->
        <tr>
          <td>STEC</td>
          <td>Adults, children</td>
          <td>Distal ileum, colon</td>
          <td>Watery diarrhea, hemorrhagic colitis, HUS</td>
          <td>Humans, animals, food, water</td>
          <td>Hydration, supportive for HUS</td>
          <td>Attaching and effacing</td>
          <td><i>eae</i><sup>+/-</sup>, <i>stx</i><sup>+</sup></td>
        </tr>

        <!-- EIEC/Shigella -->
        <tr>
          <td>EIEC/Shigella</td>
          <td>Children &lt;5 yr, adults, travelers, immunocompromised persons</td>
          <td>Colon</td>
          <td>Shigellosis/bacillary dysentery, potential HUS</td>
          <td>Humans, animals, food, water</td>
          <td>Oral rehydration, antibiotics</td>
          <td>NA (invasive)</td>
          <td><i>ipaH</i><sup>+</sup>, <i>ial</i><sup>+</sup>, <i>stx</i><sup>+</sup> (<i>S. dysenteriae</i>)</td>
        </tr>

        <!-- EAEC -->
        <tr>
          <td rowspan="3">EAEC</td>
          <td>Adults</td>
          <td rowspan="3">Small intestine and/or colon</td>
          <td>Traveler's diarrhea, HUS (<i>stx</i><sup>+</sup>)</td>
          <td rowspan="3">Food, occasionally adult carriers</td>
          <td>Antibiotics, oral rehydration</td>
          <td rowspan="3">Stacked brick and/or invasive</td>
          <td rowspan="3"><i>aatA</i><sup>+</sup>, <i>aaiC</i><sup>+</sup> other candidates</td>
        </tr>
        <tr>
          <td>Children</td>
          <td>Persistent diarrhea</td>
          <td>Antibiotics, oral rehydration, potentially probiotics</td>
        </tr>
        <tr>
          <td>Immunocompromised persons</td>
          <td>Persistent diarrhea</td>
          <td>Fluoroquinolones</td>
        </tr>

        <!-- ETEC -->
        <tr>
          <td>ETEC</td>
          <td>Children &lt;5 yr, travelers</td>
          <td>Small intestine</td>
          <td>Watery diarrhea</td>
          <td>Food, water, humans, animals</td>
          <td>Rehydration, antibiotics</td>
          <td>CF mediated</td>
          <td>CFs, LT, ST</td>
        </tr>

        <!-- DAEC -->
        <tr>
          <td>DAEC</td>
          <td>Children (increasing in severity from 18 mo to 5 yr), adults</td>
          <td>Intestine (uncharacterized location)</td>
          <td>Persistent watery diarrhea in children, speculated to contribute to Crohn's disease in adults</td>
          <td>Unknown</td>
          <td>Rehydration</td>
          <td>Diffuse adherent and/or invasive</td>
          <td>No uniform markers</td>
        </tr>

        <!-- AIEC -->
        <tr>
          <td>AIEC</td>
          <td>Adults, children</td>
          <td>Small intestine</td>
          <td>Crohn's disease</td>
          <td>Unknown</td>
          <td>Antibiotics, surgical resection</td>
          <td>NA (invasive)</td>
          <td>Uncharacterized</td>
        </tr>
      </tbody>
    </table>
  </div>

  <!-- Footer Citation -->
  <div class="footer-citation">
    (Croxen et. al., 2013)
  </div>

</div>

</body>
</html>
```
